# Now compute BFS properly with correct adjacency
adj = adj2  # use correct adjacency
start = "1679091c5a"

# BFS to find all nodes at exactly depth 4
from collections import deque

queue = deque([(start, 0)])
visited = {start: 0}
nodes_at_depth = {0: {start}}

while queue:
    node, depth = queue.popleft()
    for neighbor in adj.get(node, []):
        if neighbor not in visited:
            visited[neighbor] = depth + 1
            if depth + 1 not in nodes_at_depth:
                nodes_at_depth[depth + 1] = set()
            nodes_at_depth[depth + 1].add(neighbor)
            queue.append((neighbor, depth + 1))

print("BFS levels:")
for d in sorted(nodes_at_depth.keys()):
    print(f"Depth {d}: {sorted(nodes_at_depth[d])}")

print(f"\nNodes at exactly depth 4: {sorted(nodes_at_depth.get(4, set()))}")
```

